CREATE DATABASE IF NOT EXISTS barber_rammach CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE barber_rammach;
CREATE TABLE IF NOT EXISTS services (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(150) NOT NULL,category VARCHAR(60) NOT NULL DEFAULT 'coupe_moderne',description TEXT,price DECIMAL(8,2) NOT NULL,price_type ENUM('fixed','starting_from') NOT NULL DEFAULT 'fixed',duration INT NOT NULL,image VARCHAR(255),display_order INT NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS barbers (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,role VARCHAR(80),phone VARCHAR(25),email VARCHAR(254),image VARCHAR(255),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS appointments (id INT PRIMARY KEY AUTO_INCREMENT,service_id INT NOT NULL,barber_id INT NOT NULL,service_name VARCHAR(150) NOT NULL,displayed_price VARCHAR(80) NOT NULL,price_type ENUM('fixed','starting_from') NOT NULL DEFAULT 'fixed',customer_name VARCHAR(120) NOT NULL,customer_phone VARCHAR(25) NOT NULL,customer_email VARCHAR(254) NOT NULL,appointment_date DATE NOT NULL,appointment_time TIME NOT NULL,duration INT NOT NULL,message TEXT,status ENUM('pending','confirmed','cancelled','completed') NOT NULL DEFAULT 'confirmed',total_price DECIMAL(8,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(service_id) REFERENCES services(id),FOREIGN KEY(barber_id) REFERENCES barbers(id),INDEX availability_idx(barber_id,appointment_date,status));
CREATE TABLE IF NOT EXISTS appointment_slots (barber_id INT NOT NULL,appointment_date DATE NOT NULL,minute_of_day SMALLINT NOT NULL,appointment_id INT NOT NULL,PRIMARY KEY(barber_id,appointment_date,minute_of_day),FOREIGN KEY(barber_id) REFERENCES barbers(id),FOREIGN KEY(appointment_id) REFERENCES appointments(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS contacts (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,email VARCHAR(254) NOT NULL,phone VARCHAR(25) NOT NULL,subject VARCHAR(150) NOT NULL,message TEXT NOT NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS gallery (id INT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(150),category VARCHAR(40),image VARCHAR(255),description VARCHAR(255),position INT NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews (id INT PRIMARY KEY AUTO_INCREMENT,customer_name VARCHAR(120),review TEXT,rating TINYINT NOT NULL CHECK(rating BETWEEN 1 AND 5),image VARCHAR(255),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS closed_days (id INT PRIMARY KEY AUTO_INCREMENT,closed_date DATE NOT NULL UNIQUE,reason VARCHAR(150) NOT NULL DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS opening_hours (day_of_week TINYINT PRIMARY KEY,open_time VARCHAR(5) NOT NULL DEFAULT '09:00',close_time VARCHAR(5) NOT NULL DEFAULT '20:00',break_start VARCHAR(5) NOT NULL DEFAULT '',break_end VARCHAR(5) NOT NULL DEFAULT '',is_open BOOLEAN NOT NULL DEFAULT TRUE);
INSERT INTO opening_hours (day_of_week,open_time,close_time,break_start,break_end,is_open) VALUES (0,'09:00','20:00','','',0),(1,'09:00','20:00','','',1),(2,'09:00','20:00','','',1),(3,'09:00','20:00','','',1),(4,'09:00','20:00','','',1),(5,'09:00','20:00','','',1),(6,'09:00','20:00','','',1) ON DUPLICATE KEY UPDATE day_of_week=VALUES(day_of_week);
CREATE TABLE IF NOT EXISTS admins (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,phone VARCHAR(25),avatar VARCHAR(255),password_hash VARCHAR(255) NOT NULL,role VARCHAR(50) NOT NULL DEFAULT 'admin',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (id INT PRIMARY KEY AUTO_INCREMENT,token CHAR(64) NOT NULL UNIQUE,admin_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(100) PRIMARY KEY,setting_value LONGTEXT NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);